head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldstf31209";
scwin.i = null;
scwin.pathname = undefined;
scwin.qry = undefined;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {void}
 * @hidden N
 */
scwin.init = function () {
    const ISU_CD = $c.util.getCookie("ISU_CD");
    const COM_NM = $c.util.getCookie("COM_NM");
    $c.util.getComponent("dma_makeExcelDataReq").set("ISU_CD", ISU_CD);
    $c.util.getComponent("dma_makeExcelDataReq").set("COM_NM", COM_NM);
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

scwin.form_frmISU_CD = { action: "", method: 'post', target: '' };

try { scwin.pathname =location.pathname; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf31209' }); }

try { scwin.qry =location.search; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf31209' }); }

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldstf31209.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name img_68_onclick
 * @description img_68 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.img_68_onclick = function(e){
    try {
        scwin.isuClick('ISU_CD','COM_NM')

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf31209.img_68_onclick' }); }
};

/**
 * @method
 * @name img_68_onmouseover
 * @description img_68 onmouseover 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.img_68_onmouseover = function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        selfVar.style.cursor='hand';

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf31209.img_68_onmouseover' }); }
};

/**
 * @method
 * @name btn_openCalendarClick_onclick
 * @description btn_openCalendarClick 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_openCalendarClick_onclick = function(e){
    try {
        scwin.openCalendarClick()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf31209.btn_openCalendarClick_onclick' }); }
};

/**
 * @method
 * @name btn_Cal_onclick
 * @description btn_Cal 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Cal_onclick = async function(e){
    try {
        await scwin.cal()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldstf31209.btn_Cal_onclick' }); }
};

/**
 * @method
 * @name btn_ExcelDown_onclick
 * @description btn_ExcelDown 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_ExcelDown_onclick = async function(e){
    try {
        await scwin.excelDown()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldstf31209.btn_ExcelDown_onclick' }); }
};

/**
 * @method
 * @name btn_window_onclick
 * @description btn_window 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_window_onclick = async function(e){
    try {
        await $c.win.print()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf31209.btn_window_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_makeExcelData
 * @description make Excel Data 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_makeExcelData = async function () {
    try { return await $c.data.downFile("/bizspt/excelDown.jsp", "", ($c.util.getComponent("dma_makeExcelDataReq") ? $c.util.getComponent("dma_makeExcelDataReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};

/**
 * @method
 * @name tx_fn_Cal_xhr
 * @description Cal xhr 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Cal_xhr = async function () {
    // ⛔주소가 없다 — as-is 는 «자기 자신» 에게 제출했는데(`self_submit`) 화면 자신의 액션 URL 을
    //   하나로 못 정했다(후보 0 또는 여럿). 빈 주소로 내보내면 «조용히 엉뚱한 곳» 이다.
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_Cal_xhr"
    throw { bizMessage: "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_Cal_xhr", unresolved: "action:self_submit:tx_fn_Cal_xhr" };
};

/**
 * @method
 * @name tx_fn_ExcelDown_xhr
 * @description Excel Down xhr 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_ExcelDown_xhr = async function () {
    // ⛔주소가 없다 — as-is 는 «자기 자신» 에게 제출했는데(`self_submit`) 화면 자신의 액션 URL 을
    //   하나로 못 정했다(후보 0 또는 여럿). 빈 주소로 내보내면 «조용히 엉뚱한 곳» 이다.
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_ExcelDown_xhr"
    throw { bizMessage: "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_ExcelDown_xhr", unresolved: "action:self_submit:tx_fn_ExcelDown_xhr" };
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name isuClick
 * @description isu Click 처리
 * @param {String} ISU_CD ISU_CD
 * @param {String} COM_NM COM_NM
 * @returns {void}
 * @hidden N
 */
scwin.isuClick = function (ISU_CD, COM_NM) {
    scwin.execInit();
    IsurcdSearch2(ISU_CD, COM_NM, 315, 155);
};

/**
 * @method
 * @name openCalendarClick
 * @description open Calendar Click 처리
 * @returns {void}
 * @hidden N
 */
scwin.openCalendarClick = function () {
    scwin.execInit();
    scwin.fn_openCalendar($c.util.getComponent('ipt_submitDate'));
};

/**
 * @method
 * @name execInit
 * @description exec Init 처리
 * @returns {void}
 * @hidden N
 */
scwin.execInit = function () {
    $c.util.getComponent("ipt_submitDate").setValue("");
    $c.util.getComponent("ipt_yearStartDd").setValue("");
    $c.util.getComponent("ipt_yearEndDd").setValue("");
    $c.util.getComponent("ipt_yearMktcap").setValue("");
    $c.util.getComponent("ipt_yearYn").setValue("");
    $c.util.getComponent("ipt_mktddHaltCnt").setValue("");
    $c.util.getComponent("dma_makeExcelDataReq").set("mktddHaltYn", "");
    $c.util.getComponent("ipt_yearHalfStartDd").setValue("");
    $c.util.getComponent("ipt_yearHalfEndDd").setValue("");
    $c.util.getComponent("ipt_yearHalfMktcap").setValue("");
    $c.util.getComponent("ipt_dayHalfYn").setValue("");
    $c.util.getComponent("ipt_disclsPublDdtm").setValue("");
    $c.util.getComponent("ipt_eqtycap").setValue("");
    $c.util.getComponent("ipt_eqtycapYn").setValue("");
    $c.util.getComponent("ipt_ncorpgovncEqtycap").setValue("0");
    $c.util.getComponent("ipt_cap").setValue("");
    $c.util.getComponent("ipt_impcapRto").setValue("");
    $c.util.getComponent("ipt_impcapYn").setValue("");
    $c.util.getComponent("ipt_stkcertListDd").setValue("");
    $c.util.getComponent("ipt_stkcertPeriod").setValue("");
    $c.util.getComponent("ipt_stkcertYn").setValue("");
};

/**
 * @method
 * @name cal
 * @description cal 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.cal = async function () {
    let ISU_CD = $c.util.getComponent('ipt_ISU_CD').getValue(); if (ISU_CD == null) { ISU_CD = ''; }
    if (ISU_CD === "") {
        await $c.win.alert("[종목코드]을 선택하세요.");
        ($c.util.getComponent('ipt_ISU_CD') && $c.util.getComponent('ipt_ISU_CD').setFocus ? $c.util.getComponent('ipt_ISU_CD').setFocus() : $c.util.getComponent('ipt_ISU_CD').focus());
        return;
    }
    if (($c.util.getComponent('ipt_submitDate').getValue() == null ? '' : String($c.util.getComponent('ipt_submitDate').getValue())) === '') {
        await $c.win.alert("[신청서 제출일]을 입력하세요.");
        $c.util.getComponent("ipt_submitDate").focus();
        return;
    }
    const basicVal = $c.date.isDate($c.util.getComponent('ipt_submitDate').getValue());
    if (basicVal === false) {
        await $c.win.alert("[신청서 제출일]의 날짜형식이 정확하지 않습니다.");
        $c.util.getComponent("ipt_submitDate").focus();
        return;
    }
    let ncorpgovnc = $c.util.getComponent('ipt_ncorpgovncEqtycap').getValue();
    ncorpgovnc = ncorpgovnc.replace(/\,/gi, "");
    $c.util.getComponent("ipt_ncorpgovncEqtycap").setValue(ncorpgovnc);
    if (scwin.isNum(ncorpgovnc) === false) {
        await $c.win.alert("[최근사업연도말 비지배지분] 숫자형식만 입력하세요.");
        $c.util.getComponent("ipt_ncorpgovncEqtycap").focus();
        return;
    }
    if (($c.util.getComponent('ipt_eqtycap').getValue() == null ? '' : String($c.util.getComponent('ipt_eqtycap').getValue())) !== '' && ($c.util.getComponent('ipt_cap').getValue() == null ? '' : String($c.util.getComponent('ipt_cap').getValue())) === '') {
        await $c.win.alert("[최근사업연도말 자본금]을 입력하세요.");
        $c.util.getComponent("ipt_cap").focus();
        return;
    }
    if (($c.util.getComponent('ipt_eqtycap').getValue() == null ? '' : String($c.util.getComponent('ipt_eqtycap').getValue())) === '' && ($c.util.getComponent('ipt_cap').getValue() == null ? '' : String($c.util.getComponent('ipt_cap').getValue())) !== '') {
        await $c.win.alert("[최근사업연도말 자기자본]을 입력하세요.");
        $c.util.getComponent("ipt_eqtycap").focus();
        return;
    }
    let eqtycap = $c.util.getComponent('ipt_eqtycap').getValue();
    eqtycap = eqtycap.replace(/\,/gi, "");
    $c.util.getComponent("ipt_eqtycap").setValue(eqtycap);
    if (scwin.isNum(eqtycap) === false) {
        await $c.win.alert("[최근사업연도말 자기자본] 숫자형식만 입력하세요.");
        $c.util.getComponent("ipt_eqtycap").focus();
        return;
    }
    let capamt = $c.util.getComponent('ipt_cap').getValue();
    capamt = capamt.replace(/\,/gi, "");
    $c.util.getComponent("ipt_cap").setValue(capamt);
    if (scwin.isNum(capamt) === false) {
        await $c.win.alert("[최근사업연도말 자본금] 숫자형식만 입력하세요.");
        $c.util.getComponent("ipt_cap").focus();
        return;
    }
    $c.util.setCookie("ISU_CD", ISU_CD, 1);
    $c.util.setCookie("COM_NM", $c.util.getComponent('ipt_COM_NM').getValue(), 1);
    $c.util.getComponent("dma_makeExcelDataReq").set("ISU_CD", ISU_CD);
    $c.util.getComponent('dma_makeExcelDataReq').set('method', "processCalculateRelatedExceptionRule");
    const result = await scwin.tx_fn_Cal_xhr();
    const xmlDoc = xmlDocLoad(result);
    const dom = xmlDoc.selectNodes("//DATASET//DATA");
    if (dom.length > 0) {
        $c.util.getComponent("ipt_yearStartDd").setValue(dom.item(0).selectSingleNode('year_start_dd').text);
        $c.util.getComponent("ipt_yearEndDd").setValue(dom.item(0).selectSingleNode('year_end_dd').text);
        $c.util.getComponent("ipt_yearMktcap").setValue(dom.item(0).selectSingleNode('year1_avg_mktcap').text);
        $c.util.getComponent("ipt_yearYn").setValue(dom.item(0).selectSingleNode('year1_avg_mktcap_yn').text);
        $c.util.getComponent("ipt_mktddHaltCnt").setValue(dom.item(0).selectSingleNode('mktdd_halt_cnt').text);
        $c.util.getComponent("dma_makeExcelDataReq").set("mktddHaltYn", dom.item(0).selectSingleNode('mktdd_halt_yn').text);
        $c.util.getComponent("ipt_yearHalfStartDd").setValue(dom.item(0).selectSingleNode('year16_start_dd').text);
        $c.util.getComponent("ipt_yearHalfEndDd").setValue(dom.item(0).selectSingleNode('year_end_dd').text);
        $c.util.getComponent("ipt_yearHalfMktcap").setValue(dom.item(0).selectSingleNode('year16_mktcap').text);
        $c.util.getComponent("ipt_dayHalfYn").setValue(dom.item(0).selectSingleNode('year16_mktcap_yn').text);
        $c.util.getComponent("ipt_disclsPublDdtm").setValue(dom.item(0).selectSingleNode('discls_publ_ddtm').text);
        $c.util.getComponent("ipt_eqtycap").setValue(dom.item(0).selectSingleNode('eqtycap_amt').text);
        $c.util.getComponent("ipt_eqtycapYn").setValue(dom.item(0).selectSingleNode('eqtycap_amt_yn').text);
        $c.util.getComponent("ipt_ncorpgovncEqtycap").setValue(dom.item(0).selectSingleNode('ncorpgovnc_eqtycap').text);
        $c.util.getComponent("ipt_cap").setValue(dom.item(0).selectSingleNode('cap_amt').text);
        $c.util.getComponent("ipt_impcapRto").setValue(dom.item(0).selectSingleNode('impcap').text);
        $c.util.getComponent("ipt_impcapYn").setValue(dom.item(0).selectSingleNode('impcap_yn').text);
        $c.util.getComponent("ipt_stkcertListDd").setValue(dom.item(0).selectSingleNode('stkcert_list_dd').text);
        $c.util.getComponent("ipt_stkcertPeriod").setValue(dom.item(0).selectSingleNode('stkcert_period').text);
        $c.util.getComponent("ipt_stkcertYn").setValue(dom.item(0).selectSingleNode('stkcert_yn').text);
    }
};

/**
 * @method
 * @name isNum
 * @description is Num 처리
 * @param {String} str str
 * @returns {void}
 * @hidden N
 */
scwin.isNum = function (str) {
    for (scwin.i = 0; scwin.i < str.length; scwin.i++) {
        const cv = str.charCodeAt(scwin.i);
        if (!(0x30 <= cv && cv <= 0x39)) {
            return false;
        }
    }
    return true;
};

/**
 * @method
 * @name excelDown
 * @description excel Down 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.excelDown = async function () {
    if (($c.util.getComponent('ipt_yearStartDd').getValue() == null ? '' : String($c.util.getComponent('ipt_yearStartDd').getValue())) === '') {
        await $c.win.alert("[계산하기]을 실행 후 다운로드 할 수 있습니다.");
        return;
    }
    $c.util.getComponent("dma_makeExcelDataReq").set("ISU_CD", $c.util.getComponent('ipt_ISU_CD').getValue());
    $c.util.getComponent('dma_makeExcelDataReq').set('method', "processCalculateRelatedExceptionRuleExcel");
    const result = await scwin.tx_fn_ExcelDown_xhr();
    await scwin.makeExcelData(result);
};

/**
 * @method
 * @name makeExcelData
 * @description make Excel Data 처리
 * @param {*} xml xml
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.makeExcelData = async function (xml) {
    const xmlDoc = xmlDocLoad(xml);
    const dom = xmlDoc.selectNodes("//DATASET//DATA");
    let excelData = "";
    excelData += "<table class='table_board_default_3' width='880' border='1' id='id_excelData' style='display:none'";
    excelData += "<tr>";
    excelData += "<td class='board_subject_3' width='150' align='center'>종목코드</td>";
    excelData += "<td class='board_subject_3' width='180' align='center'>거래일</td>";
    excelData += "<td class='board_subject_3' width='150' align='center'>매매거래정지여부</td>";
    excelData += "<td class='board_subject_3' width='200' align='center'>시가총액</td>";
    excelData += "<td class='board_subject_3' width='200' align='center'>종가</td>";
    excelData += "<td class='board_subject_3' width='200' align='center'>수정주가</td>";
    excelData += "<td class='board_subject_3' width='200' align='center'>상장주식수</td>";
    excelData += "</tr>";
    for (scwin.i = 0; scwin.i < dom.length; scwin.i++) {
        excelData += "<tr>";
        excelData += "<td class='board_title_2'>" + dom.item(scwin.i).selectSingleNode('isu_cd').text + "</td>";
        excelData += "<td class='board_title_2'>" + dom.item(scwin.i).selectSingleNode('calnd_dd').text + "</td>";
        excelData += "<td class='board_title_2'>" + dom.item(scwin.i).selectSingleNode('halt_yn').text + "</td>";
        excelData += "<td class='board_title_2'>" + dom.item(scwin.i).selectSingleNode('mktcap').text + "</td>";
        excelData += "<td class='board_title_2'>" + dom.item(scwin.i).selectSingleNode('tdd_clsprc').text + "</td>";
        excelData += "<td class='board_title_2'>" + dom.item(scwin.i).selectSingleNode('stockprice').text + "</td>";
        excelData += "<td class='board_title_2'>" + dom.item(scwin.i).selectSingleNode('list_shrs').text + "</td>";
        excelData += "</tr>";
    }
    excelData += "</table>";
    self.id_excelData.outerHTML = excelData;
    $c.util.getComponent('dma_makeExcelDataReq').set('excelData', self.id_excelData.outerHTML);
    scwin.form_frmISU_CD.method = "post";
    scwin.form_frmISU_CD.target = "_blank";
    await scwin.tx_makeExcelData();
};
